INSERT INTO `weibo_note_comment` VALUES (111, '7785563903', '折一碗月', 'https://tvax2.sinaimg.cn/crop.0.0.1080.1080.180/008uTqPlly8huqzf2kyhaj30u00u078n.jpg?KID=imgbed,tva&Expires=1780997224&ssig=T1vo8cBnW9', 'f', 'https://m.weibo.cn/u/7785563903?launchid=10000360-page_H5', '山东', 1780986424439, 1780986424439, 5307887893089358, 5307883493524852, '选择题好难第一次做了40分钟哈哈，前面去年选择题计时做了20分钟，这次直接➕20哈哈哈，大题也很无语对，题量怎么大根本做不完，考唯物辩证法联系直接说联系呗，哈哈哈真无语', 1781011352, '2026-06-09 13:22:32+08:00', '11', '2', '5307887893089358');
