INSERT INTO `weibo_note_comment` VALUES (113, '6237975605', '薛定谔的猫有一只喵喵', 'https://tvax1.sinaimg.cn/default/images/default_avatar_female_180.gif?KID=imgbed,tva&Expires=1780997224&ssig=RgeHIlfEHa', 'f', 'https://m.weibo.cn/u/6237975605?launchid=10000360-page_H5', '安徽', 1780986424454, 1780986424454, 5307896898259401, 5307883493524852, '别怕，生物、地理、化学、生物不都是赋分制了吗？你难人亦难，都是省内排位赋分，最终还是公平的。', 1781013499, '2026-06-09 13:58:19+08:00', '0', '1', '5307896898259401');
INSERT INTO `weibo_note_comment` VALUES (114, '7892270010', '微博智搜', 'https://tvax2.sinaimg.cn/crop.0.0.1080.1080.180/008C79XAly8i5grzh416kj30u00u0t8z.jpg?KID=imgbed,tva&Expires=1780997224&ssig=CopoPw8g5z', 'f', 'https://m.weibo.cn/u/7892270010?launchid=10000360-page_H5', '', 1780986424461, 1780986424461, 5307903877581342, 5307883493524852, '评论区反映山东高考政治卷难度超预期，考生普遍焦虑选择题耗时长大题无从下笔，预估分数低。但多数人通过赋分制宽慰，强调“你难大家也难”关注排名公平。部分吐槽题型创新如经济考国际、必修考文化，备考套路失效。非山东考生则庆幸未考此卷或对难度惊讶。查看最新戳-&gt;微博智搜', 1781015163, '2026-06-09 14:26:03+08:00', '0', '0', '5307903877581342');
