INSERT INTO `weibo_note_comment` VALUES (130, '5611802047', '小智的路卡利欧', 'https://tvax4.sinaimg.cn/crop.0.0.640.640.180/0067My4fly8hobnq7u624j30hs0hs74p.jpg?KID=imgbed,tva&Expires=1780997238&ssig=V6Aqh1kgh7', 'm', 'https://m.weibo.cn/u/5611802047?launchid=10000360-page_H5', '浙江', 1780986438044, 1780986438044, 5307846155043815, 5307845428908312, '本来高考要筛选的就是顶尖那一撮人才，至于普通学校，意义就是单纯找个地方让人在不懂事的年纪有个事做罢了', 1781001401, '2026-06-09 10:36:41+08:00', '20', '5', '5307846155043815');
INSERT INTO `weibo_note_comment` VALUES (131, '6505556311', '夜半孤酒忆清欢', 'https://tvax1.sinaimg.cn/crop.0.0.960.960.180/0076gEnBly8ia4for4utuj30qo0qo409.jpg?KID=imgbed,tva&Expires=1780997238&ssig=lrrqYlpsQg', 'm', 'https://m.weibo.cn/u/6505556311?launchid=10000360-page_H5', '黑龙江', 1780986438052, 1780986438052, 5307854066029154, 5307845428908312, '学新闻媒体吧，看看wwc，，天天随便发发，也不用管真假，就吃的饱饱的，是不是很有奔头', 1781003287, '2026-06-09 11:08:07+08:00', '14', '0', '5307854066029154');
