INSERT INTO `weibo_note_comment` VALUES (133, '6140874581', '降妖除魔李火旺', 'https://tvax3.sinaimg.cn/crop.0.0.851.851.180/006HAu0dly8hj91a6p2glj30nn0nnwg3.jpg?KID=imgbed,tva&Expires=1780997238&ssig=5r%2BcH%2FLWVa', 'm', 'https://m.weibo.cn/u/6140874581?launchid=10000360-page_H5', '山东', 1780986438066, 1780986438066, 5307856028175627, 5307845428908312, '并没有弱化，反而一直在加强，普通岗位一样有学历要求，你不是全日制本科不能考教师这些职业，本科进厂和专科中专进厂待遇能一样？', 1781003755, '2026-06-09 11:15:55+08:00', '5', '3', '5307856028175627');
INSERT INTO `weibo_note_comment` VALUES (134, '6281723574', 'Vanillaware-', 'https://tvax2.sinaimg.cn/crop.0.0.1080.1080.180/006R7tgaly8i5tobwu94zj30u00u00v4.jpg?KID=imgbed,tva&Expires=1780997238&ssig=CCMUjHqagd', 'f', 'https://m.weibo.cn/u/6281723574?launchid=10000360-page_H5', '四川', 1780986438076, 1780986438076, 5307845810851980, 5307845428908312, '我看武大文科就业挺好的啊', 1781001319, '2026-06-09 10:35:19+08:00', '4', '5', '5307845810851980');
INSERT INTO `weibo_note_comment` VALUES (135, '6330351017', '深夜吉他爱好者', 'https://tvax1.sinaimg.cn/crop.0.0.1001.1001.180/006UpvtLly8hh5kgy2aedj30rt0rtwgt.jpg?KID=imgbed,tva&Expires=1780997238&ssig=8iad2IkUxb', 'f', 'https://m.weibo.cn/u/6330351017?launchid=10000360-page_H5', '福建', 1780986438083, 1780986438083, 5307845911250051, 5307845428908312, '是的，除了顶尖的学历和专业，其他的都没有那么重要，大学四年不过是给年轻人一个“暑假”让他们再玩玩，也给国家缓解就业压力', 1781001343, '2026-06-09 10:35:43+08:00', '8', '0', '5307845911250051');
INSERT INTO `weibo_note_comment` VALUES (136, '7299454632', '用户7299454632', 'https://tvax1.sinaimg.cn/default/images/default_avatar_female_180.gif?KID=imgbed,tva&Expires=1780997238&ssig=tjCVx2LVxP', 'f', 'https://m.weibo.cn/u/7299454632?launchid=10000360-page_H5', '浙江', 1780986438092, 1780986438092, 5307848563361275, 5307845428908312, '我的感觉是现在的大学，你不能单纯的理解还是校园，不能按部就班的读完大学，出社会再积累经验。你要知道社会这两年的风向是什么，就业机会在哪里，针对性的培训你的技能，才能找到岗位。而不是出社会才开始学， 现在大学的教程跟社会上公司的就业岗位内容相差的太大了。', 1781001975, '2026-06-09 10:46:15+08:00', '4', '0', '5307848563361275');
INSERT INTO `weibo_note_comment` VALUES (137, '2185587695', 'ChZzh小豪', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/82456befly8i5hj5m26e7j20u00u040w.jpg?KID=imgbed,tva&Expires=1780997238&ssig=qfRoEkTbaV', 'm', 'https://m.weibo.cn/u/2185587695?launchid=10000360-page_H5', '安徽', 1780986438099, 1780986438099, 5307845832871009, 5307845428908312, '我感觉现在可以学一门手艺哪种职校比普通的大学更好', 1781001324, '2026-06-09 10:35:24+08:00', '2', '1', '5307845832871009');
