INSERT INTO `weibo_note_comment` VALUES (153, '7928768218', '哈哈ha0615', 'https://tvax3.sinaimg.cn/crop.0.0.1080.1080.180/008EAiOmly8hqzgnzwat1j30u00u0jv4.jpg?KID=imgbed,tva&Expires=1780997244&ssig=kfqlxhKYY8', 'f', 'https://m.weibo.cn/u/7928768218?launchid=10000360-page_H5', '上海', 1780986444823, 1780986444823, 5307208859913401, 5307206845335523, '那年的夏天，我记忆尤深，某一天，我拿了98分，妈妈说之前100分，怎么退步了？然后打了我一巴掌，结果到了晚上，我突然发了高烧，下着大暴雨，但妈妈却背着发高烧的我，骑着单车载着我…….', 1780849458, '2026-06-07 16:24:18+08:00', '236', '5', '5307208859913401');
