INSERT INTO `weibo_note_comment` VALUES (168, '3762961402', '崔庆龙_', 'https://tvax2.sinaimg.cn/crop.0.0.921.921.180/e04a3bfaly8hfi8a0j7w6j20pl0pl3zx.jpg?KID=imgbed,tva&Expires=1780997252&ssig=MrbR9mesvl', 'm', 'https://m.weibo.cn/u/3762961402?launchid=10000360-page_H5', '四川', 1780986452953, 1780986452953, 5307883432706776, 5307882226059057, '图片评论', 1781010288, '2026-06-09 13:04:48+08:00', '6', '0', '5307883432706776');
INSERT INTO `weibo_note_comment` VALUES (169, '5910088929', 'Aria琼琼', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/006rY86Zly8i7e19mz5jaj30u00u0acw.jpg?KID=imgbed,tva&Expires=1780997252&ssig=l2AdwnwuMk', 'f', 'https://m.weibo.cn/u/5910088929?launchid=10000360-page_H5', '中国香港', 1780986452971, 1780986452971, 5307883921342582, 5307882226059057, '高考重要，努力重要，老师重要，平台重要，但更重要的是，一个人能不能慢慢学会真正思考，学会从“我必须赢过别人”转向“我到底要把自己带到哪里”。', 1781010404, '2026-06-09 13:06:44+08:00', '17', '0', '5307883921342582');
INSERT INTO `weibo_note_comment` VALUES (170, '3789944022', '言心心理', 'https://tvax4.sinaimg.cn/crop.0.0.1024.1024.180/e1e5f4d6ly8h8imzx9qgjj20sg0sg776.jpg?KID=imgbed,tva&Expires=1780997252&ssig=HhsS4wbeBv', 'f', 'https://m.weibo.cn/u/3789944022?launchid=10000360-page_H5', '广东', 1780986452983, 1780986452983, 5307885657525098, 5307882226059057, '想起个人的一些经历，可能我们真正恐惧的不是失去某些重大的机会，也不是某一次的挫折和失利，而是这种所谓的“错过”和“挫败”，带来的对于自身心智的破坏性，这使得一个人思考和自我安抚的内在空间被强烈的情绪淹没甚至摧毁。', 1781010819, '2026-06-09 13:13:39+08:00', '4', '1', '5307885657525098');
INSERT INTO `weibo_note_comment` VALUES (171, '1598311427', '興趣班_', 'https://tvax2.sinaimg.cn/crop.0.0.828.828.180/5f444c03ly8gp80vilz15j20n00n0tak.jpg?KID=imgbed,tva&Expires=1780997252&ssig=i9qVVqpmn0', 'f', 'https://m.weibo.cn/u/1598311427?launchid=10000360-page_H5', '浙江', 1780986452993, 1780986452993, 5307884032232830, 5307882226059057, '学历可以给你去到某一些圈层的入场券，但它们不能给你真实体验，如何找到心之所向如何完善自我人格如何在更广阔的游戏里选择适合自己的生活方式，这些都是要你去一点点试出来的。在尝试的过程中积累的所有体验和历练会让你越来越有底气越来越感觉到圆满，这时放眼回看，当初高考所得已经给不了更多了', 1781010432, '2026-06-09 13:07:12+08:00', '2', '0', '5307884032232830');
INSERT INTO `weibo_note_comment` VALUES (172, '3849478104', '_茕孑立', 'https://tvax4.sinaimg.cn/crop.102.0.755.755.180/e5725fd8ly8gbuwy4roudj20qo0kzab0.jpg?KID=imgbed,tva&Expires=1780997252&ssig=xuT5jzRjLi', 'f', 'https://m.weibo.cn/u/3849478104?launchid=10000360-page_H5', '四川', 1780986453001, 1780986453001, 5307888492873428, 5307882226059057, '“我们只有在与这个世界产生最真实的摩擦力时，当下的际遇才能成为助力我们前行的跃迁之地。”', 1781011495, '2026-06-09 13:24:55+08:00', '1', '0', '5307888492873428');
INSERT INTO `weibo_note_comment` VALUES (173, '6581440990', '黄金之心Psy', 'https://tvax2.sinaimg.cn/crop.0.0.1080.1080.180/007bp3s2ly8hxq6lifus8j30u00u0mxn.jpg?KID=imgbed,tva&Expires=1780997252&ssig=BAgvvGjDEF', 'f', 'https://m.weibo.cn/u/6581440990?launchid=10000360-page_H5', '江苏', 1780986453008, 1780986453008, 5307888014198971, 5307882226059057, '高考结束，也是成年生活的正式开启，许多能力在成年人的生活中，都将比应试能力要占据更大的权重，最基本的一项，作为独立的个体，有能力管理，照顾好自己的生活', 1781011381, '2026-06-09 13:23:01+08:00', '1', '0', '5307888014198971');
INSERT INTO `weibo_note_comment` VALUES (174, '2345318120', '离开台湾八百米', 'https://tvax1.sinaimg.cn/crop.0.0.1080.1080.180/8bcab6e8ly8iaknebi0spj20u00u040c.jpg?KID=imgbed,tva&Expires=1780997252&ssig=xcDl%2FJKw6%2F', 'm', 'https://m.weibo.cn/u/2345318120?launchid=10000360-page_H5', '江苏', 1780986453016, 1780986453016, 5307902812488192, 5307882226059057, '关于“江苏人”（只有在这个语境才会这么说）的人格，中小学教育经历塑造的那一部分很难忽略', 1781014908, '2026-06-09 14:21:48+08:00', '0', '0', '5307902812488192');
INSERT INTO `weibo_note_comment` VALUES (175, '5228314435', '月亮是一颗小星球', 'https://tvax1.sinaimg.cn/crop.0.0.720.720.180/005HPtqbly8i42bnd9wvjj30k00k0mxx.jpg?KID=imgbed,tva&Expires=1780997252&ssig=Lyri7M08Jq', 'f', 'https://m.weibo.cn/u/5228314435?launchid=10000360-page_H5', '江西', 1780986453023, 1780986453023, 5307904150210902, 5307882226059057, '不害怕数学，但是所有条件摆出来的数学就像是一团毛线，找不到头。', 1781015228, '2026-06-09 14:27:08+08:00', '0', '0', '5307904150210902');
INSERT INTO `weibo_note_comment` VALUES (176, '5637415558', '窗外在下叶子雨', 'https://tvax4.sinaimg.cn/crop.0.0.607.607.180/0069w1joly8hul83n5n6kj30gv0gvmxq.jpg?KID=imgbed,tva&Expires=1780997252&ssig=vURDc8fr0R', 'f', 'https://m.weibo.cn/u/5637415558?launchid=10000360-page_H5', '重庆', 1780986453039, 1780986453039, 5307904024642217, 5307882226059057, '以前高中数学老觉得学不懂，高考也没考好，复读了。复读的时候，遇见的那个数学老师，他一讲我就懂了，成绩提高了很多。那时候才意识到遇见一个和自己思维方式相像的老师很重要。（老师也是人，人和人的相处真的很吃缘分。）再后来，上大学了，读研了，发现自己之前并不是笨，只是自己是学的比较慢……', 1781015198, '2026-06-09 14:26:38+08:00', '0', '0', '5307904024642217');
INSERT INTO `weibo_note_comment` VALUES (177, '1956489241', '河谷云野', 'https://tvax4.sinaimg.cn/crop.0.0.815.815.180/749da819ly8idmjgmkxomj20mn0mn42k.jpg?KID=imgbed,tva&Expires=1780997252&ssig=53bhcQLjQI', 'f', 'https://m.weibo.cn/u/1956489241?launchid=10000360-page_H5', '湖北', 1780986453047, 1780986453047, 5307902487430242, 5307882226059057, '功夫在画外', 1781014832, '2026-06-09 14:20:32+08:00', '0', '0', '5307902487430242');
INSERT INTO `weibo_note_comment` VALUES (178, '1805497280', '黄诺嫚', 'https://tvax3.sinaimg.cn/crop.0.0.1080.1080.180/6b9db3c0ly8hq3z9qzosqj20u00u0q4m.jpg?KID=imgbed,tva&Expires=1780997252&ssig=%2FbfsPQ9yc6', 'f', 'https://m.weibo.cn/u/1805497280?launchid=10000360-page_H5', '广东', 1780986453055, 1780986453055, 5307901289694082, 5307882226059057, '记忆中的数学在初三，初二数学28分上初三的我，学立体几何硬是从40多分涨到81分，老师在念80分以上同学的名字，念到我的名字，声调都高了若干个分贝。哎，加减乃人生～', 1781014545, '2026-06-09 14:15:45+08:00', '0', '0', '5307901289694082');
INSERT INTO `weibo_note_comment` VALUES (179, '5932190118', 'ranran星辰', 'https://tvax3.sinaimg.cn/crop.0.0.1080.1080.180/006tsRDMly8ha5t879wv6j30u00u0gok.jpg?KID=imgbed,tva&Expires=1780997252&ssig=c97k3rW%2FDD', 'f', 'https://m.weibo.cn/u/5932190118?launchid=10000360-page_H5', '广东', 1780986453068, 1780986453068, 5307887664761431, 5307882226059057, '转发微博', 1781011298, '2026-06-09 13:21:38+08:00', '0', '0', '5307887664761431');
