INSERT INTO `weibo_note_comment` VALUES (181, '6990403137', '螺蛳粉重度偏爱者', 'https://tvax2.sinaimg.cn/crop.0.0.812.812.180/007D51bHly8hqa7tnel0tj30mk0mkq5n.jpg?KID=imgbed,tva&Expires=1780997261&ssig=xFEVeOYiuL', 'f', 'https://m.weibo.cn/u/6990403137?launchid=10000360-page_H5', '四川', 1780986461318, 1780986461318, 5307221934081224, 5307220986433200, '张雪峰老师，我还记得你。', 1780852575, '2026-06-07 17:16:15+08:00', '7282', '131', '5307221934081224');
INSERT INTO `weibo_note_comment` VALUES (182, '7296611621', '吉他会哭', 'https://tvax1.sinaimg.cn/crop.0.0.720.720.180/007XNQ0dly8idka3ccaq0j30k00k0aas.jpg?KID=imgbed,tva&Expires=1780997261&ssig=VbalxaoSs8', 'm', 'https://m.weibo.cn/u/7296611621?launchid=10000360-page_H5', '福建', 1780986461336, 1780986461336, 5307223263938662, 5307220986433200, '张雪峰老师，我还记得你， 一句一句把我拉出迷雾里，那些年少的愁，你替我扛起。风再大，我也会继续前进， 你给过的勇气，我一直放在心里。', 1780852892, '2026-06-07 17:21:32+08:00', '2740', '17', '5307223263938662');
